"""
Ankle activity dashboard: viewer + runner for the UNO Q wearable.

    py dashboard.py            # connects to the board over MQTT, opens http://localhost:8765
    py dashboard.py --demo     # fake data, no board needed (to see the UI)

Only needs paho-mqtt (already installed). It subscribes to PREFIX/live and PREFIX/status and
sends 'live' to PREFIX/cmd as soon as it connects (and again if the board restarts), so predictions
start on their own.
"""
import argparse, json, random, threading, time, webbrowser
from collections import deque
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

BROKER, PORT = "broker.hivemq.com", 1883
PREFIX = "ME193/Kabir/ankle"
CMD, STATUS, LIVE = PREFIX + "/cmd", PREFIX + "/status", PREFIX + "/live"
MODELS = ["model1_tree", "model1_knn", "model2_tree", "model2_knn"]

S = {"mqtt": False, "board": "unknown", "board_seen": 0.0, "last": None, "last_at": 0.0,
     "paused": False, "hist": deque(maxlen=360), "log": deque(maxlen=30)}
lock = threading.Lock()
client = None


def log(msg):
    S["log"].appendleft({"t": time.time(), "m": msg})


def on_status(text):
    S["board_seen"] = time.time()
    low = text.lower()
    if low.startswith("live"): S["board"] = "live"
    elif low.startswith("armed"): S["board"] = "armed"
    elif low.startswith("recording"): S["board"] = "recording"
    elif low.startswith(("done", "stopped", "online")): S["board"] = "idle"
    log(text)


def on_live(msg):
    S["last"], S["last_at"], S["board"], S["board_seen"] = msg, time.time(), "live", time.time()
    S["hist"].append(msg)


def mqtt_start():
    global client
    import paho.mqtt.client as mqtt
    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)

    def on_connect(c, u, f, rc, p):
        c.subscribe([(STATUS, 1), (LIVE, 0)])
        with lock:
            S["mqtt"] = True; log("connected to broker")
        send("live")

    def on_disconnect(c, u, f, rc, p):
        S["mqtt"] = False

    def on_message(c, u, m):
        try:
            text = m.payload.decode(errors="ignore")
            with lock:
                if m.topic == LIVE: on_live(json.loads(text))
                else: on_status(text)
            if m.topic == STATUS and text.lower().startswith("online"):
                send("live")             # board (re)started: switch it to live mode
        except Exception as e:
            print("bad message:", e)

    client.on_connect, client.on_disconnect, client.on_message = on_connect, on_disconnect, on_message
    client.reconnect_delay_set(1, 10)
    client.connect_async(BROKER, PORT, 30)
    client.loop_start()
    threading.Thread(target=keep_live, daemon=True).start()


def demo_start():
    S["mqtt"] = True
    def run():
        acts = [("still", .01), ("walking", .8), ("running", 2.6), ("biking", 1.3), ("walking", .9), ("still", .01)]
        i, n = 0, 0
        while True:
            act, pk = acts[i % len(acts)]
            time.sleep(0.6)
            def pr(a): return a if random.random() > .12 else random.choice(["still", "walking", "running", "biking"])
            p = {m: pr(act) for m in MODELS}
            if n == 0: p["model1_tree"] = "biking" if act == "walking" else p["model1_tree"]
            hist = [h["preds"] for h in list(S["hist"])[-2:]] + [p]
            sm = {m: max(set(h[m] for h in hist), key=[h[m] for h in hist].count) for m in MODELS}
            with lock:
                if n == 0: S["board"] = "live"
                on_live({"t": time.time(), "peak": round(pk * random.uniform(.8, 1.2), 3), "preds": p, "smooth": sm,
                         "agree": p["model1_tree"] == p["model2_tree"]})
            n += 1
            if n >= 7: n, i = 0, i + 1
    threading.Thread(target=run, daemon=True).start()


def keep_live():
    """If no predictions are arriving, keep asking the board to go live (the first command can be lost)."""
    while True:
        time.sleep(4)
        if client is None or S["paused"] or not S["mqtt"]:
            continue
        if S["last_at"] == 0 or time.time() - S["last_at"] > 5:
            send("live")


def send(text):
    if client is None:
        with lock: log("demo: would send '%s'" % text)
        return True
    r = client.publish(CMD, text, qos=1)
    if text in ("stop", "live"): S["paused"] = text == "stop"
    with lock: log("sent: " + text)
    return r.rc == 0


def state():
    with lock:
        now = time.time()
        return {"now": now, "mqtt": S["mqtt"], "board": S["board"], "board_age": now - S["board_seen"] if S["board_seen"] else None,
                "last": S["last"], "msg": S["log"][0]["m"] if S["log"] else "", "last_age": now - S["last_at"] if S["last_at"] else None,
                "hist": list(S["hist"]), "log": list(S["log"])}


class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass

    def _send(self, body, ctype):
        b = body.replace("__ICONS__", json.dumps(ICONS)).encode()
        self.send_response(200); self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(b))); self.send_header("Cache-Control", "no-store")
        self.end_headers(); self.wfile.write(b)

    def do_GET(self):
        if self.path.startswith("/api/state"): self._send(json.dumps(state()), "application/json")
        else: self._send(PAGE, "text/html; charset=utf-8")

    def do_POST(self):
        n = int(self.headers.get("Content-Length", 0))
        text = self.rfile.read(n).decode().strip()
        ok = bool(text) and len(text) < 100 and send(text)
        self._send(json.dumps({"ok": ok}), "application/json")


ICONS = json.loads('{"biking": "data:image/png;base64,", "running": "data:image/png;base64,", "walking": "data:image/png;base64,", "still": "data:image/png;base64,"}')

